
import type { Lesson, Topic } from './types';
import manifest from './manifest.json';
const dirs=manifest.lessons;
const starts: NonNullable<Lesson['start']>[] = [
  {
    "problem": "A program can change a number or switch an LED, but the same write instruction may do either. You need to know what receives the write.",
    "outcome": "Identify CPU working storage, program memory, changing memory and pin controls; explain why the destination address changes the result.",
    "firstExperiment": [
      "Select SRAM in Store destination and keep Word to store at 32.",
      "Click Execute store and watch the SRAM word change while the LED stays unchanged.",
      "Select GPIOA BSRR and click Execute store; compare the output latch and PA5 LED with the earlier RAM result."
    ]
  },
  {
    "problem": "One C assignment can become several CPU instructions. The hardware does not change when the CPU is still calculating its new value.",
    "outcome": "Trace loads, calculations and stores; distinguish address values from contents and identify the instruction that changes the peripheral.",
    "firstExperiment": [
      "Select Actual SystemInit excerpt and leave Initial FLASH ACR at 263.",
      "Advance the sequence one step at a time, watching CPU registers and the FLASH ACR value.",
      "Stop at STR and compare the final ACR 0x101 with the initial 0x107; identify which bits changed."
    ]
  },
  {
    "problem": "The bytes kept in Flash and the writable values used in SRAM are not the same arrangement. This can make an array cost memory in more than one place.",
    "outcome": "Follow the build stages and predict the Flash and SRAM needs of code, constants, initialized data and zero-initialized data.",
    "firstExperiment": [
      "In Object storage select Zero-initialized writable array and set Object payload bytes to 1024.",
      "Read the Flash and RAM payload results, then select Initialized writable array.",
      "Select Used constant array and compare all three choices; explain where each runtime value lives."
    ]
  },
  {
    "problem": "Main and an interrupt handler can both increment a shared counter. Although only one CPU instruction runs at a time, their separate steps can overwrite one another.",
    "outcome": "Explain a lost update and distinguish fresh volatile reads from protection of an entire shared operation.",
    "firstExperiment": [
      "Select After load, before add in Arrival position and leave protection unchecked.",
      "Advance the sequence and watch the handler increment 10 to 11 before main stores its old calculation.",
      "Enable Protect main update with PRIMASK and repeat the sequence; explain why the final count now reaches 12."
    ]
  },
  {
    "problem": "Reset cannot immediately run normal C code: the stack and global variable values must first be prepared. Missing preparation can appear as an unrelated program bug.",
    "outcome": "Trace reset into startup and identify which preparation step supplies each global value and handler address.",
    "firstExperiment": [
      "Keep Vector table at boot Flash base enabled and uncheck Copy .data to SRAM.",
      "Advance the sequence to the witness results and compare the initialized and zero-initialized variables.",
      "Re-enable the copy, uncheck Clear .bss and repeat; identify the different witness that now fails."
    ]
  },
  {
    "problem": "A stored output bit does not always drive a pin, and a detected button edge does not always run a handler. Each part of the path needs its own configuration.",
    "outcome": "Connect a GPIO command to its physical output and locate missing steps between a pin transition and its interrupt handler.",
    "firstExperiment": [
      "Select header D13 / PA5, keep the GPIOA clock enabled and choose output mode.",
      "Choose Set output latch and click Execute BSRR store; watch ODR bit 5 and LD4.",
      "Change Selected pin mode to analog while keeping the latch set; explain why the stored value and driven output differ."
    ]
  },
  {
    "problem": "Software can be delayed by other work. A timer can create or timestamp edges in hardware, so you need to distinguish actual edge time from handler response time.",
    "outcome": "Calculate a timer period and pulse width, explain buffered updates and measure how handler delay changes a software timestamp.",
    "firstExperiment": [
      "Leave PSC at 47, ARR at 19999 and CCR1 at 1500; read the frame time and high duration.",
      "Set CCR1 to 1000 and watch the high duration shorten while the frame time stays fixed.",
      "In the capture comparison set rising delay to 10 and falling delay to 100 microseconds; compare capture width with ISR-read width."
    ]
  }
];

const topic=(title:string,simple:string,why:string,mechanism:string,technical:string,experiment:string,source:string|undefined,code:string|undefined,steps:string[],remember:string):Topic=>({title,simple,why,mechanism,technical,experiment,source,code,steps,remember});
function lesson(id:number,subtitle:string,youKnow:string[],adds:string[],why:string,topics:Topic[],question:string,options:string[],correct:number,explanations:string[],terms: [string,string][],recap:string[],limitations:string[]=[]):Lesson{return {id,start:starts[id],shortTitle:['Inside a small computer','How the CPU follows instructions','From C code to a running program','When two jobs share data','What happens when the board starts','Reading pins and handling events','Measuring time and making pulses'][id],subtitle,prerequisites:id?[id-1]:[],youKnow,adds,why,topics,prediction:{question,options,correct,explanations},terms:terms.map(([term,meaning])=>({term,meaning})),recap,sources:dirs[id].files.filter(f=>/\.(md|c|h|ld)$/.test(f)),limitations};}
export const foundations:Lesson[]=[
lesson(0,'Understand where instructions, data and hardware controls live.', ['A program performs instructions in order. No electronics knowledge needed.'],['One address space','CPU working registers','Hardware registers','Modes, stacks and exceptions'],'To make a program control an LED, you must know where its instructions run, where its changing values live and which write reaches the pin hardware. This lesson connects those places so a stored number and a changed output have an understandable cause.',[
topic("What is inside this small computer?","A Nucleo is a board with a tiny computer chip on it. Inside the chip, a central processor (CPU) follows instructions. Flash remembers those instructions when power is off. SRAM is short-term work space for changing values. Built-in helpers called peripherals can control pins or communicate with devices.","A write has a destination. Write to ordinary memory and a number changes. Write to the pin controller and an electrical output can change. This difference explains why one C assignment can light an LED while another only saves a value.","The CPU reads its next instruction from Flash. It uses small work slots called registers while it calculates. A load copies a value from an address into a register; a store copies a value back. If the address belongs to SRAM, a number is saved. If it belongs to a pin peripheral, the hardware can change a signal on the board.",'Target: STM32C031C6 on Nucleo-C031C6; ARM Cortex-M0+, ARMv6-M, 32 KiB Flash and 12 KiB SRAM. Course SystemInit selects 48 MHz; reset clock is HSI48 divided by four. This diagram is a functional model, not silicon floorplan.','Select each machine component. Explain why instructions remain after unplugging while a running counter does not.','00_Architecture/Slide.md',undefined,["Flash keeps the program even when power is removed.", "The CPU reads an instruction from Flash and performs its operation.", "Small CPU storage locations called registers hold the numbers being worked on.", "Static random-access memory (SRAM) holds changing values while powered.", "A peripheral receives a command and can change a signal at a pin."],"Same store instruction, different destination: SRAM saves a number; a GPIO address can change a pin."),
topic("How a numbered address selects memory or hardware","An address is a number identifying a location the CPU can read or write. Numbers beginning with 0x are written in hexadecimal, base sixteen. Some addresses select stored data; others select hardware controls. A store means sending a value to the chosen address.","Writing the right number to the wrong address can change the wrong memory value or device. Knowing the destination lets you predict whether a write merely remembers a value or changes a physical output.","The CPU supplies a value and a destination address. The bus, the connection carrying these requests, routes the request by its address. At 0x20000000 SRAM stores the number for a later read. At 0x50000018 the GPIO pin-control hardware interprets the number as output commands. With the pin configured as an output, those commands can change the LED.",'Main Flash: 0x08000000–0x08007FFF. SRAM: 0x20000000–0x20002FFF. GPIOA base: 0x50000000. ODR offset 0x14; BSRR offset 0x18. Boot alias at zero depends on selected boot memory; it is not a second Flash. Region boundaries are not promises that every address is implemented.','Try Flash end 0x08007FFF, then 0x08008000. Predict why one is implemented and the other is outside main Flash.','04_Startup_And_LinkerScript/link.ld',undefined,["The CPU supplies a value and a destination address.", "The bus, the connection carrying these requests, routes the request by its address.", "At 0x20000000 SRAM stores the number for a later read.", "At 0x50000018 the GPIO pin-control hardware interprets the number as output commands.", "With the pin configured as an output, those commands can change the LED."],"The address decides where a write goes and therefore what it can do."),
topic("Two kinds of register with different jobs","A register is a small named place for a value. CPU registers such as R0 hold operands: numbers an instruction works on. Peripheral registers are addressed hardware interfaces. A control register changes settings, a status register reports conditions, and a data register receives or supplies data.","A calculation inside the CPU does not automatically change a pin. Separating CPU working values from device settings tells you when the hardware actually receives the result and why reading a device can also affect its state.","A load instruction copies a value from an address into CPU register R0. An arithmetic instruction changes that working value inside the CPU. A store sends a working value to an address. If the address selects a peripheral control, the hardware uses the value to change its behavior.",'R0–R12 are general-purpose; R13 is SP (stack pointer), R14 LR (link/return address), R15 PC. xPSR contains flags, Thumb state and exception number. Byte/halfword loads exist; 32-bit CPU does not mean all accesses must be 32-bit.','Use the RAM/device store experiment. Tell which value changed and which physical output changed.','00_Architecture/Slide.md',undefined,["A load instruction copies a value from an address into CPU register R0.", "An arithmetic instruction changes that working value inside the CPU.", "A store sends a working value to an address.", "If the address selects a peripheral control, the hardware uses the value to change its behavior."],"Changing R0 changes CPU working data; a hardware register changes only when it is accessed."),
topic("How interrupted work resumes","A stack is an area of RAM where values are saved and later restored in reverse order. An exception is a CPU-managed interruption that runs a handler, a function responding to an event. Saving the interrupted values lets that function run without losing the earlier work.","The handler will use CPU working storage that the interrupted program was already using. Without saving and restoring those values and the resume address, the earlier calculation could continue with the wrong numbers or at the wrong instruction.","Ordinary program instructions run in the CPU state called Thread mode. An exception causes the CPU to save working values and the resume address on a stack. The vector table, a list of handler addresses, identifies the function to run. The CPU enters Handler mode and executes that function. Exception return restores the saved values and continues the interrupted work.",'Thread mode may use MSP or PSP selected by CONTROL.SPSEL; Handler mode uses MSP and is privileged. STM32C031 has no desktop-style virtual memory. PRIMASK masks configurable exceptions, not NMI or HardFault. Architectural registers are reached with MRS/MSR, not peripheral addresses.','Replay the exception overview. Name the saved PC’s purpose before learning any interrupt acronym.','00_Architecture/Slide.md',undefined,["Ordinary program instructions run in the CPU state called Thread mode.", "An exception causes the CPU to save working values and the resume address on a stack.", "The vector table, a list of handler addresses, identifies the function to run.", "The CPU enters Handler mode and executes that function.", "Exception return restores the saved values and continues the interrupted work."],"The saved program address tells the CPU where the interrupted work must resume."),
topic("Bytes, aligned addresses and enabling hardware","A bit is one binary digit, 0 or 1. Eight bits make a byte; a 32-bit word occupies four bytes at four consecutive addresses. Alignment means starting a wider access at a suitable boundary. Hardware also needs its clock enabled and its pin connected to the intended function.","A word read from an unsuitable address can fail on this CPU. Even a correctly addressed output command may produce no visible output if the hardware clock is disabled or the pin is connected to another function.","Writing word 0x12345678 places bytes 78, 56, 34 and 12 at increasing addresses on this chip. Starting that word at an address divisible by four gives an aligned word access. Enabling the peripheral clock allows the relevant hardware to operate. Selecting the pin mode connects the output to that pin. Only then can the configured output produce the intended signal.",'Cortex-M0+ does not support unaligned halfword/word data accesses. STM32 is little-endian. Clock gate behavior is peripheral-specific; this course checks register readback. Increase Flash wait-state setting before clock frequency. A read of PC can observe instruction address + 4; it is not always the next fetch address.','Choose RAM word address ending 0, then ending 1. Predict why only the first is naturally aligned. Turn the GPIO clock off in lesson 05 and inspect the missing path.','00_Architecture/Slide.md',undefined,["Writing word 0x12345678 places bytes 78, 56, 34 and 12 at increasing addresses on this chip.", "Starting that word at an address divisible by four gives an aligned word access.", "Enabling the peripheral clock allows the relevant hardware to operate.", "Selecting the pin mode connects the output to that pin.", "Only then can the configured output produce the intended signal."],"A four-byte word needs a four-byte boundary; a useful output needs both clock and pin configuration.")
],'Which store can make the on-board LED change?', ['A store to SRAM 0x20000000','A store to GPIOA BSRR 0x50000018','Every store anywhere'],1,['SRAM retains a number; another action would have to copy it to a device.','Correct: BSRR commands GPIO output state. Clock and output mode must also be configured.','Addresses select destinations. Most stores do not control pins.'],[['Microcontroller','A CPU, memory and peripherals integrated into one chip.'],['Memory-mapped I/O','Memory-mapped input/output: device controls and status have numbered addresses the CPU can read or write.'],['Register','A small named value location: CPU registers hold working values; peripheral registers expose hardware settings, status or data.'],['SRAM','Static random-access memory: writable storage for working values and stacks while powered; startup prepares C globals.'],['Flash','Memory retaining program instructions and fixed values when power is removed.'],['Exception','An interruption managed by the CPU: it saves working state, runs the selected handler and can restore the earlier work.'],['Vector table','Table containing initial stack pointer and handler addresses.'],['MSP / PSP','Main stack pointer / process stack pointer: registers marking the current stack boundary in RAM. Handler mode uses MSP; Thread mode can select either.'],['RCC','Reset and clock control: hardware registers selecting clock sources and dividers and enabling clocks for other peripherals.'],['Little-endian','The byte holding the lowest eight bits of a multi-byte number is stored at the lowest address.']],['An address is a number selecting the memory location or hardware interface that a load or store reaches.','A peripheral interprets register writes as settings or commands, which can change physical outputs.','Enable the peripheral clock, select the pin function and write the documented control bits to complete the output path.'],['Address explorer models documented regions and key registers, not every valid device register.']),
lesson(1,'Follow each instruction from address to actual state change.', ['CPU registers hold working values. A load reads an addressed value; a store writes one.','Flash keeps program bytes without power; SRAM holds changing values while powered.'],['Thumb encodings','Flags and branches','Literal pools','Calls and stack frames'],'A C line can perform several separate CPU operations before hardware changes. Following those instructions shows when a value is read, when it is calculated and when it is finally written, so you can explain the result and where an interruption matters.',[
topic("Read one instruction and watch one change","The CPU understands small actions called instructions. One C statement can become several actions. LDR means “load”: copy a value from an address into a CPU work slot. STR means “store”: copy a work-slot value to an address. Disassembly is the list of these actions made from your C code.","A C line can take several steps before hardware changes. Finding the store step tells you when the new setting reaches the peripheral. It also shows where an interrupt could pause the work.","First the CPU reads the old setting into a work slot. It clears the bits it wants to change, then puts the new bits in. Those calculations only change CPU work slots. STR sends the finished value to the Flash control address. The hardware setting changes when that store arrives.",'Cortex-M0+ executes Thumb instructions, mostly 16-bit encodings with some 32-bit forms such as BL. It has no A32 state, no hardware divide, and no FPU. Code density comparisons are program-dependent, not a universal fixed saving.','Start ACR at 0x00000107. Predict which bits survive the latency change. Step to STR and check result 0x00000101.','01_Instruction_Set/Slide.md','FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_0;',["The CPU puts a small number into one work slot.", "LDR copies the current setting from its address into another work slot.", "The CPU clears the old choice bits, then writes the new choice bits into its work slot.", "STR sends the finished value to the hardware address.", "The peripheral setting changes at that store, after the CPU calculations."],"Follow the store instruction to find when the hardware setting changes."),
topic("How load and store use an address","A pointer is a value used as an address. LDR means load: read the contents at an address into a CPU register. STR means store: write a CPU register value to an address. The address and the contents stored there are different numbers.","Adding one to a value in RAM requires bringing it into the CPU, calculating and sending it back. Confusing the address with the value would make you calculate with the location number or write to an unintended destination.","R1 holds the address of the value to read. LDR R0, [R1] reads that location and puts its contents in R0. R1 still holds the address; it did not become the contents. An offset adds a distance in bytes to the starting address when selecting a nearby location. STR sends a register value to the selected destination.",'16-bit Thumb word immediate offset is a five-bit field scaled by four: 0–124 bytes. Byte offsets reach 0–31; halfword 0–62. SP-relative word offset reaches 1020. Width and alignment must match the target register specification.','Select the ACR load frame and compare R1 before/after. Explain why R2 still holds 0x40022000.','01_Instruction_Set/Slide.md',undefined,["R1 holds the address of the value to read.", "LDR R0, [R1] reads that location and puts its contents in R0.", "R1 still holds the address; it did not become the contents.", "An offset adds a distance in bytes to the starting address when selecting a nearby location.", "STR sends a register value to the selected destination."],"The address tells you where; the loaded value tells you what was there."),
topic("Why loading a constant can read Flash","An instruction has a limited number of bits to encode its operation and operands. Some constants are too large to fit inside it. The compiler can store them near the instructions in Flash, in a group called a literal pool, and generate a load to read them.","The CPU must be able to obtain a large device address even when that number does not fit in the instruction itself. Keeping the number nearby in Flash provides it, but creates an extra read you must distinguish from reading the device.","The compiler places the large peripheral address in a nearby Flash word. A load uses the program counter (PC), the code-position register, to locate that word. The read copies 0x40022000 into R2. A later load uses R2 to read the FLASH peripheral setting. These two reads visit different addresses and obtain different kinds of value.",'Actual 4a0b at 0x08000230 loads from Align(PC+4,4)+44 = 0x08000260. That word contains 0x40022000, FLASH register block base. PC-relative LDR is a memory read, not an immediate assignment.','Pause after literal load. Identify which address was read and which address is now in R2.','01_Instruction_Set/Slide.md',undefined,["The compiler places the large peripheral address in a nearby Flash word.", "A load uses the program counter (PC), the code-position register, to locate that word.", "The read copies 0x40022000 into R2.", "A later load uses R2 to read the FLASH peripheral setting.", "These two reads visit different addresses and obtain different kinds of value."],"Loading an address from Flash does not yet read the device at that address."),
topic("How a comparison decides a branch","Flags are single-bit CPU results recording facts about a calculation. A branch changes which instruction runs next. CMP compares two values by subtracting internally, then a conditional branch checks the resulting flags. The compared values themselves stay unchanged.","A program needs to take different actions when values are equal, smaller or larger. The comparison result must reach the instruction choosing the path; another calculation that replaces the flags can change that decision.","CMP subtracts the second operand from the first for the comparison. Equal operands produce zero, so the zero flag Z becomes 1. BEQ checks Z and takes the branch when Z is 1. BNE takes the branch when Z is 0. Other conditions distinguish signed numbers, which can be negative, from unsigned numbers.",'APSR flags: N negative, Z zero, C carry/no borrow, V signed overflow. BNE tests Z=0. BLT tests N != V; BCC tests C=0. Flag-setting arithmetic can overwrite a comparison result before a branch.','Step the call/compare experiment. Predict branch for R0=3 compared with 3; inspect all four flags.','01_Instruction_Set/Slide.md',undefined,["CMP subtracts the second operand from the first for the comparison.", "Equal operands produce zero, so the zero flag Z becomes 1.", "BEQ checks Z and takes the branch when Z is 1.", "BNE takes the branch when Z is 0.", "Other conditions distinguish signed numbers, which can be negative, from unsigned numbers."],"CMP records a comparison in flags; a later branch reads those flags."),
topic("How a function call finds its way back","Calling a function transfers execution to its instructions. The CPU must also remember where the caller should continue. The link register (LR) holds that return address. A function making another call must preserve its own return address because the next call replaces LR.","A second call replaces the one return address held in LR. Unless the earlier address has been saved, the original function no longer has the information needed to return to its own caller.","BL records the address after the call in LR, then branches to the function. If the function will call another function, it saves the needed return state on the stack. PUSH moves the stack pointer (SP) down and writes saved values into RAM. A nested call may now change LR without losing the original return address. POP restores saved values; restoring the program counter (PC) resumes the caller.",'AAPCS passes first four word arguments in R0–R3; R0 returns ordinary word results. R4–R11 are callee-saved; R12 is scratch. Stack is full-descending and maintained eight-byte aligned at public interfaces. Cortex-M targets require Thumb bit on indirect control transfer.','Watch SP decrease on PUSH then return to the initial value on POP. Explain why leaf functions may not need to save LR.','01_Instruction_Set/Slide.md',undefined,["BL records the address after the call in LR, then branches to the function.", "If the function will call another function, it saves the needed return state on the stack.", "PUSH moves the stack pointer (SP) down and writes saved values into RAM.", "A nested call may now change LR without losing the original return address.", "POP restores saved values; restoring the program counter (PC) resumes the caller."],"Each unfinished call needs its own preserved return address.")
],'When does FLASH ACR actually change in the stepper?', ['When LDR loads its address','When BICS changes R1','When STR writes R3 through R2'],2,['LDR loads an address from a literal pool into R2, not a new register setting.','BICS modifies a CPU register only. Hardware still has the old ACR value.','Correct: STR puts the combined word on the bus at FLASH ACR’s address.'],[['Thumb','The instruction set executed by Cortex-M; ARMv6-M supports a defined subset.'],['LDR / STR','Load a value into a register / store a register value to an address.'],['Literal pool','Constants near code loaded with PC-relative addressing.'],['APSR','Application Program Status Register: the CPU result flags N (negative), Z (zero), C (carry/no borrow) and V (signed overflow). Flags form part of xPSR, the combined processor status register.'],['LR','Link register, holding a normal call return address or exception-return value.'],['AAPCS','ARM Architecture Procedure Call Standard: the rules functions share for passing arguments, returning results and preserving registers.']],['Loads bring addressed values into CPU registers; stores write register values to addressed destinations.','Flags connect comparisons with branches.','Before a nested call replaces LR, preserve the earlier return address so the original caller can resume.'],['SystemInit excerpt uses opcodes from pinned lecture; browser state model is not an ELF executor or cycle-accurate emulator. Call/branch example is explicitly simplified.']),
lesson(2,'Understand how build tools place the program and its data.', ['Instructions run from Flash.','Writable data belongs in SRAM.'],['Build pipeline','Symbols and relocation','Sections and Flash/RAM costs','ELF, BIN and HEX'],'Before the board can run C code, build tools must turn it into instructions, connect functions across files and place bytes at chip addresses. Understanding those steps helps explain missing definitions and why one writable array can need both Flash and RAM.',[
topic("How C text becomes instructions in Flash","A toolchain is the set of programs that builds firmware, the program loaded onto the board. These tools translate source text, combine files and choose addresses. Each stage solves a different problem before the chip can run the result.","The chip executes encoded instructions rather than C source text. Code written in separate files must also agree on the final location of every function they call, so translation and joining are both necessary.","The preprocessor expands includes and macros into C text. The compiler translates C operations into assembly instructions. The assembler encodes instructions in object files, which are separately built pieces. The linker combines those pieces and assigns final memory addresses. Conversion tools produce a programming image, which a programmer writes into Flash.",'The course driver uses -mcpu=cortex-m0plus -mthumb, -Os, -g3, C11, section-per-function/data, CMSIS include paths, nano.specs and --gc-sections. Lesson 04 owns startup/link.ld; later lessons use shared target defaults.','At each build stage ask: are addresses final yet? Predict which stage can report undefined reference.','_build/build-lesson.bat',undefined,["The preprocessor expands includes and macros into C text.", "The compiler translates C operations into assembly instructions.", "The assembler encodes instructions in object files, which are separately built pieces.", "The linker combines those pieces and assigns final memory addresses.", "Conversion tools produce a programming image, which a programmer writes into Flash."],"The linker is the stage that joins separately built pieces and chooses final addresses."),
topic("How a name gets connected to a definition","A declaration tells the compiler the name and type of something used by your code. A definition supplies its function body or storage. A symbol is a name recorded by the build tools. The linker matches references to definitions so instructions can use the correct addresses.","A compiler can build a file that calls a function without seeing that function’s body. Before execution, the build must find a real definition and connect the call to its address; declaring the name in a header alone cannot supply that body.","One file uses a declared function or variable while its definition may be in another file. The object file records a reference that still needs an address. The linker finds the definition and chooses where it belongs. It fixes the recorded references, called relocations, to use that address. A missing definition produces an undefined-reference error.",'CMSIS declares SystemCoreClock; course startup defines it. Linker script provides _sdata and _edata as addresses. Build-time address binding has no OS loader to relocate this bare-metal firmware later.','Explain why including a header does not supply the body of a function. Inspect _startup/c031c6/startup.c for SystemCoreClock’s definition.','_startup/c031c6/startup.c',undefined,["One file uses a declared function or variable while its definition may be in another file.", "The object file records a reference that still needs an address.", "The linker finds the definition and chooses where it belongs.", "It fixes the recorded references, called relocations, to use that address.", "A missing definition produces an undefined-reference error."],"A header can declare a function; the linker still needs a file containing its definition."),
topic("Where code and three kinds of data live","A section groups bytes with the same storage needs. Instructions and read-only values can stay in Flash. A writable variable with a nonzero initial value needs both a saved initial copy in Flash and working storage in SRAM. Zero-initialized writable data needs SRAM that startup code clears.","SRAM is limited, and writable variables need storage that can change during execution. Separating storage needs avoids wasting RAM on instructions and fixed values while still giving writable data its correct initial values.","The linker groups instructions in .text and read-only values in .rodata. For .data it reserves SRAM and stores the initial bytes in Flash. Startup copies those initial bytes to SRAM before main runs. For .bss it reserves SRAM without a full stored zero image. Startup writes zeros into that reserved region.",'Flash .data location is LMA (load memory address); SRAM .data location is VMA (virtual/run address). .bss is normally NOBITS: memory size without equivalent file payload. Const placement also depends on use and optimizer; unused objects can disappear.','Make a 1024-byte table const, initialized writable, then zero-initialized. Compare Flash and RAM costs.','04_Startup_And_LinkerScript/link.ld',undefined,["The linker groups instructions in .text and read-only values in .rodata.", "For .data it reserves SRAM and stores the initial bytes in Flash.", "Startup copies those initial bytes to SRAM before main runs.", "For .bss it reserves SRAM without a full stored zero image.", "Startup writes zeros into that reserved region."],".data needs an initial Flash copy plus SRAM; .bss needs SRAM plus startup clearing."),
topic("What ELF, BIN and HEX contain","ELF, the Executable and Linkable Format, keeps program bytes together with addresses and information useful to debugging. BIN is a raw byte image. Intel HEX is a text format containing bytes and their destination addresses. A programmer uses the selected format to place the right bytes in Flash.","The chip needs program bytes at the correct addresses, while a person debugging also needs names and source information. Using the right file format prevents writing file metadata as if it were instructions or loading raw bytes at the wrong starting address.","The linker produces an ELF file with placed sections and symbols. The objcopy tool extracts program bytes into BIN or HEX. For BIN the programmer must be told the matching starting address. HEX records carry address information with the bytes. The programmer writes the image to those Flash locations so reset can find the startup words.",'Actual lecture HEX record begins :020000040800F2; upper address is 0x0800. Debug information is not Flash payload. The programmer’s base for BIN must match link.ld because BIN does not carry destination addresses.','Explain why flashing the entire ELF file as raw bytes would be wrong. Step to firmware stage and name which information BIN omits.','02_Development/Slide.md',undefined,["The linker produces an ELF file with placed sections and symbols.", "The objcopy tool extracts program bytes into BIN or HEX.", "For BIN the programmer must be told the matching starting address.", "HEX records carry address information with the bytes.", "The programmer writes the image to those Flash locations so reset can find the startup words."],"BIN needs a separately supplied destination; HEX includes addresses."),
topic("Choose a tool for the question you have","Building proves that tools could translate and join the code. It cannot prove that a physical pin responds as intended. Inspection tools show what was built, while a simulator runs a model of the board. Each result answers a specific question and has a specific limit.","A successful build cannot show whether a button or timer behaves correctly. A simulator may also leave out a hardware feature, so choosing a tool for a specific question prevents treating missing modeled behavior as proof that the code is wrong.","Build firmware so there is a concrete program to inspect. Use size for storage, nm for named symbols and objdump for encoded instructions. Use the linker map to see why sections occupy their addresses. Run the image in a simulator to inspect behavior its model supports. Check a real board when the question depends on actual electrical or timing behavior.",'Course reports are pinned historical evidence, not measurements performed by this browser. The interactive models are educational. Simulator limitations are carried into timer and DMA lessons.','Find a strong handler symbol versus weak default in the source. Explain why a successful linker run can still leave a misspelled handler unused.','02_Development/Slide.md',undefined,["Build firmware so there is a concrete program to inspect.", "Use size for storage, nm for named symbols and objdump for encoded instructions.", "Use the linker map to see why sections occupy their addresses.", "Run the image in a simulator to inspect behavior its model supports.", "Check a real board when the question depends on actual electrical or timing behavior."],"A successful build proves translation and linking; pin behavior needs behavioral evidence.")
],'A 1024-byte zero-initialized array needs how much object payload in Flash?', ['1024 bytes for its zeros','No equivalent zero payload; startup clears its SRAM','No RAM either'],1,['.bss reserves memory without storing a byte-for-byte zero image.','Correct: SRAM size is still 1024 bytes; startup performs clearing. There may be small unrelated code/alignment costs.','The array exists at runtime and needs RAM even though its zeros need no stored copy.'],[['Toolchain','Tools translating source into a placed executable image.'],['Linker','Resolves symbols and places sections at addresses.'],['ELF','Executable format with sections, addresses, symbols and optional debug data.'],['.data','Writable initialized globals: initial bytes in Flash, runtime values in RAM.'],['.bss','Zero-initialized writable storage; startup writes the zeros.'],['.rodata','Read-only data generally placed in Flash.'],['LMA / VMA','Load address of initial bytes / runtime address of a section.']],['Linker chooses final chip addresses.','.data consumes both Flash and RAM.','.bss reserves SRAM; startup must write zeros there before main begins.'],['Section cost explorer shows payload only; alignment, library code, heap/stack reservation and optimization add actual build costs.']),
lesson(3,'See why an interrupted update can lose a change.', ['Incrementing a RAM value reads it, adds one in a CPU register and writes it back.','An interrupt saves the current working values and resume address, runs a handler, then restores them.'],['Polling, interrupts and DMA','Volatile versus atomicity','Lost updates and tearing','Priorities and latency'],'Main and an interrupt handler can both change one RAM value. If the handler runs between main’s read and write, one change can be lost even though each instruction works correctly. This lesson shows the failure and the short protection needed to prevent it.',[
topic("Polling, interrupts and direct memory access","Polling means the CPU repeatedly checks whether hardware is ready. An interrupt lets hardware request a handler while ordinary code does other work. Direct memory access (DMA) lets another hardware unit move data between a peripheral and memory, avoiding a CPU copy for every item.","Repeatedly checking a slow device keeps the CPU occupied even when nothing is ready. Notifications free it to do other work during the wait, and hardware data transfers reduce the number of items the CPU must copy itself.","With polling, the CPU reads status and repeats the test until it changes. With interrupts, main continues until an eligible hardware request starts a handler. The handler performs the work and returns to main. With DMA, a configured hardware unit responds to requests and transfers the data itself. The CPU can do other work while DMA transfers, although both may compete for the memory bus.",'Polling is often suitable for a brief known wait. An interrupt is not parallel CPU execution: it preempts the current context. DMA is an independent bus master and can contend for bus access.','Replay the exception path, then trace which actor moves data for each of the three arrangements.','03_Execution_Concurrency/Slide.md',undefined,["With polling, the CPU reads status and repeats the test until it changes.", "With interrupts, main continues until an eligible hardware request starts a handler.", "The handler performs the work and returns to main.", "With DMA, a configured hardware unit responds to requests and transfers the data itself.", "The CPU can do other work while DMA transfers, although both may compete for the memory bus."],"Polling checks readiness; interrupts request CPU work; DMA moves configured data."),
topic("What volatile changes about a read","The compiler may reuse a previously read ordinary value when the program allows that optimization. An interrupt or device can change a shared value outside the current code path. Marking the object volatile tells the compiler to preserve the required accesses, allowing repeated checks to obtain fresh values.","A loop that keeps testing an earlier value can wait forever after a handler has changed the actual flag. Fresh accesses let it notice that change, but do not stop another handler from running between the steps of an update.","The waiting loop first sees flag value 0. An interrupt changes the flag in RAM to 1. A possible ordinary-object optimization keeps testing the earlier cached zero. A volatile loop reads the object again when evaluating its condition. It can therefore observe 1 and stop waiting, but a multi-step update still needs protection.",'Volatile does not provide mutual exclusion, make counter++ atomic, or act as a general memory-ordering mechanism. ISR-sharing rules require toolchain/architecture awareness. It is not a substitute for C atomics in standard multithreaded code.','Toggle volatile and inject flag=1 in the visibility experiment. Then show why a fresh load still does not save a compound increment.','03_Execution_Concurrency/Slide.md',undefined,["The waiting loop first sees flag value 0.", "An interrupt changes the flag in RAM to 1.", "A possible ordinary-object optimization keeps testing the earlier cached zero.", "A volatile loop reads the object again when evaluating its condition.", "It can therefore observe 1 and stop waiting, but a multi-step update still needs protection."],"Volatile preserves accesses; it does not prevent interruption between accesses."),
topic("Why two increments can produce only one increase","Incrementing a variable usually requires reading it, adding one in a CPU register and writing it back. If a handler changes the shared variable after main has read it, main can later overwrite that newer value with its own calculation from the old value. This is a lost update.","The defect depends on exactly when the handler runs, so many ordinary runs can appear correct. Naming the read, calculation and write explains which arrival positions lose an update and lets you test that specific failure.","Main reads counter 10 into its working register. An interrupt runs before main stores its result. The handler reads 10, adds one and stores 11. Main resumes with its saved old value 10 and calculates 11. Main stores 11, replacing the handler result instead of advancing it to 12.",'A race condition depends on timing. Atomic means indivisible at the relevant observation boundary. A critical section needs mutual exclusion. Cortex-M0+ has no LDREX/STREX; interrupt masking protects main/ISR operations on this single core, not independent DMA or another core.','Run all four arrival positions. Identify exactly which store destroys the update. Enable protection and rerun identical position.','03_Execution_Concurrency/Slide.md',undefined,["Main reads counter 10 into its working register.", "An interrupt runs before main stores its result.", "The handler reads 10, adds one and stores 11.", "Main resumes with its saved old value 10 and calculates 11.", "Main stores 11, replacing the handler result instead of advancing it to 12."],"Two calculations from the same old value can overwrite each other."),
topic("Finish the shared update before allowing its handler","A critical section is a short region protected from another context that could interfere with its data. On this single CPU, temporarily masking configurable interrupts delays their handlers while main completes its shared update. PRIMASK is the CPU register controlling that mask.","If an interfering handler runs halfway through an update, it can invalidate the value main is using. Delaying it only for the needed steps protects the update; restoring the earlier mask avoids accidentally enabling handlers that were already disabled.","Save the existing PRIMASK value so the earlier interrupt policy can be restored. Set the mask before main begins the shared load, add and store. An arriving configurable interrupt remains pending instead of entering its handler. Main completes the update while its old snapshot is still valid. Restore the saved mask; when allowed, the handler uses the completed new value.",'Safer reusable pattern: save __get_PRIMASK(); __disable_irq(); update; __set_PRIMASK(saved). NMI and HardFault remain unmasked. Critical sections cannot make a device’s incoming data wait indefinitely; its buffer may overflow.','Enable protection and watch the pending event occur after the store. Explain why this changes latency rather than erasing the event.',undefined,'uint32_t saved = __get_PRIMASK();\n__disable_irq();\ncounter++;\n__set_PRIMASK(saved); // teaching robust pattern',["Save the existing PRIMASK value so the earlier interrupt policy can be restored.", "Set the mask before main begins the shared load, add and store.", "An arriving configurable interrupt remains pending instead of entering its handler.", "Main completes the update while its old snapshot is still valid.", "Restore the saved mask; when allowed, the handler uses the completed new value."],"Protect the entire read-change-write sequence and restore the previous mask."),
topic("Why two individually safe reads can disagree","A logical value can consist of multiple fields, such as an event count and its measured width. Each aligned word can be read completely, yet an interrupt between those reads can change both fields. The reader then obtains a pair that never existed together. This mixture is called tearing.","A count and its measurement describe the same sample. Reading them from different versions can report a result that was never produced, even though each individual number was read completely.","The reader loads the count from the old sample. A handler runs and replaces both count and width with a new sample. The reader resumes and loads the new width. Its old count and new width form an inconsistent pair. Protecting both reads makes them describe the same sample.",'A 64-bit value takes multiple transfers on this 32-bit core. A single aligned 32-bit load/store does not make read-modify-write atomic. A read-and-clear flag can lose a second event; a plain assignment clear need not be a read-modify-write.','Move interrupt between pair reads in the tearing experiment; compare observed pair with the two actual versions.','06_Time_And_Timers/Main.c',undefined,["The reader loads the count from the old sample.", "A handler runs and replaces both count and width with a new sample.", "The reader resumes and loads the new width.", "Its old count and new width form an inconsistent pair.", "Protecting both reads makes them describe the same sample."],"One complete word read does not guarantee a consistent pair of words."),
topic("How priority and waiting affect response time","The nested vectored interrupt controller (NVIC) selects which pending, enabled interrupt the CPU may handle. A lower priority number means greater urgency on this chip. Latency is the delay between an event arriving and its handler beginning; it includes time spent waiting for other work or interrupt masks.","A slow handler can keep another event waiting until its response is too late or incoming data is lost. Knowing which requests may interrupt which handlers helps you keep urgent responses short and account for their actual waiting time.","A device records an event and requests an interrupt. The controller checks whether that request is enabled and allowed by the current mask. If other handlers are active, their priority affects whether the new request must wait. The CPU saves interrupted state and starts the selected handler. Long handlers and long critical sections increase the waiting portion of latency.",'STM32C031 implements two priority bits: 0 most urgent through 3 least. CMSIS shifts numeric priorities into the implemented high byte bits. For ordinary scalar instructions this model waits for completion; ARM also defines interruptible/restartable multi-transfer instructions (PUSH, POP, LDM, STM). Latency includes masking, higher-priority work and exception entry; no universal exact duration is claimed here.','With protection enabled, identify where event arrived versus where handler started. Why is that distance latency?','03_Execution_Concurrency/Slide.md',undefined,["A device records an event and requests an interrupt.", "The controller checks whether that request is enabled and allowed by the current mask.", "If other handlers are active, their priority affects whether the new request must wait.", "The CPU saves interrupted state and starts the selected handler.", "Long handlers and long critical sections increase the waiting portion of latency."],"An event being pending means it awaits service; priority and masks decide when service starts.")
],'Volatile counter++ runs in main and ISR. What prevents a lost update?', ['Volatile alone','Mutual exclusion around main’s entire update','Making the counter uint64_t'],1,['Volatile ensures accesses remain observable; it does not stop the interrupt between them.','Correct for this main/ISR single-core model: defer eligible ISR until update completes, preserving prior mask.','A larger value can require more transfers and add tearing.'],[['Volatile','A C type qualifier requiring the compiler to preserve accesses to the object; it provides no protection against interruption.'],['Atomicity','An operation happens as one indivisible action from the viewpoint of the relevant other code or hardware.'],['Race condition','Outcome depends on interleaving of contexts accessing shared state.'],['Critical section','A code region protected so another interfering context cannot change its shared state halfway through the operation.'],['Tearing','Reading pieces from different versions of one logical value.'],['PRIMASK','CPU register used to delay configurable exception handlers; non-maskable interrupt and HardFault are unaffected.'],['Latency','Time between an event and the response beginning.']],['Volatile preserves accesses; mutual exclusion prevents another context from interfering during a shared update.','Protect the complete operation or related group of fields so readers cannot obtain an unfinished result.','Short handlers and short critical sections preserve response time.'],['Event-level instruction model; does not claim cycle timing or estimate real failure frequency.']),
lesson(4,'Trace the startup work that prepares C before main.', ['The linker combines built files and assigns the final addresses used by instructions.','.data keeps initial bytes in Flash and writable working values in SRAM; startup copies between them.'],['Reset vectors','Startup copy and zero loops','Linker symbols and stack bounds','Clock and printf setup'],'The CPU does not enter main with every C variable automatically prepared. Startup code must first establish the stack, copy initialized data and clear zero-initialized data. Tracing that preparation explains why a program can start yet read incorrect global values.',[
topic("What reset reads before any C function runs","Reset does not search for a function named main. The CPU reads two words from its boot vector table: the initial stack pointer and the first instruction address. A vector table is a fixed list of startup and handler addresses prepared by the program build.","Even startup software may call functions and save values, so the stack must be ready before that software begins. Fixed startup words give the CPU a definite stack boundary and first instruction without needing a running program to find them.","The selected boot memory appears at the CPU boot address. The CPU loads vector word 0 into the main stack pointer (MSP). It loads vector word 1 as the Reset_Handler address, with its Thumb state bit. Reset_Handler can now use the stack while preparing the program. Only after software initialization does startup call main.",'link.ld places KEEP(*(.isr_vector)) first in Flash. _estack = 0x20000000 + 12 KiB = 0x20003000, one past SRAM end; first PUSH decrements before writing. A handler vector’s bit 0 marks Thumb state.','Disable correct vector placement and reset. Explain why the CPU cannot search later in Flash for the intended table.','04_Startup_And_LinkerScript/startup.c',undefined,["The selected boot memory appears at the CPU boot address.", "The CPU loads vector word 0 into the main stack pointer (MSP).", "It loads vector word 1 as the Reset_Handler address, with its Thumb state bit.", "Reset_Handler can now use the stack while preparing the program.", "Only after software initialization does startup call main."],"Reset supplies the stack and Reset_Handler address; startup software reaches main."),
topic("How startup gives global variables their initial values","A global variable exists throughout the program, so C expects it to have a specified initial value before main starts. Writable nonzero initial values are stored in Flash but used from SRAM. Zero-initialized variables have SRAM reserved for them. Startup must prepare both regions explicitly.","C code expects global variables to have their specified values before main begins, but existing RAM contents cannot guarantee that. Explicit copying and clearing keep that promise; a simulator starting RAM at zero could otherwise conceal the missing work.","The linker identifies the Flash copy and SRAM destination for .data. Reset_Handler copies the stored initial bytes into that SRAM span. It then writes zero throughout the .bss span. The initialized witness should now hold 0x00C0FFEE and the zero witness should hold 0. Skipping either loop breaks the corresponding promise, even though Flash instructions remain intact.",'Actual course data_witness = 0x00C0FFEE; bss_witness = 0. Startup symbols describe half-open ranges. The model deliberately starts RAM with selected nonzero garbage, not a claim about silicon reset values.','Skip each loop separately. Explain why .rodata remains correct while writable witnesses fail.','04_Startup_And_LinkerScript/Main.c',undefined,["The linker identifies the Flash copy and SRAM destination for .data.", "Reset_Handler copies the stored initial bytes into that SRAM span.", "It then writes zero throughout the .bss span.", "The initialized witness should now hold 0x00C0FFEE and the zero witness should hold 0.", "Skipping either loop breaks the corresponding promise, even though Flash instructions remain intact."],"Startup copies .data and clears .bss before main reads globals."),
topic("Why startup takes the address of a linker symbol","The linker script defines labels marking section boundaries, such as _sdata at the beginning of writable initialized data. Such a label names an address. It is not an ordinary variable whose stored value contains that address. Startup takes the label address to know where copying begins and ends.","Copying needs the boundary’s location, not the bytes already stored at that location. Treating a linker label like a variable containing a pointer would start the copy from the wrong information.","The linker places .data and assigns its boundary labels. Startup uses &_sdata to obtain the first destination address. It advances the destination through the region until &_edata, the first address after it. Subtracting the end and start addresses gives the span size. Reading bytes at _sdata instead would obtain data stored there, not the boundary address.",'RAM (rw) origin 0x20000000 length 12K; Flash (rx) origin 0x08000000 length 32K. .data > RAM AT> FLASH; _sidata = LOADADDR(.data). Heap and downward stack share scarce RAM; static fit does not prove runtime stack/heap safety.','Use size explorer, then compute end minus start. Shrink a claimed SRAM size and identify the corresponding initial stack boundary.','04_Startup_And_LinkerScript/link.ld',undefined,["The linker places .data and assigns its boundary labels.", "Startup uses &_sdata to obtain the first destination address.", "It advances the destination through the region until &_edata, the first address after it.", "Subtracting the end and start addresses gives the span size.", "Reading bytes at _sdata instead would obtain data stored there, not the boundary address."],"A boundary label tells where storage begins; taking its address obtains that location."),
topic("How a handler name reaches the vector table","The startup file supplies default interrupt functions as weak definitions, meaning a matching normal definition can replace them. Your handler must have exactly the expected name. The vector table refers to that name, so a spelling mismatch can leave the default function connected even when the build succeeds.","An interrupt needs a real function address in its table before it occurs. A misspelled handler can leave the fallback connected despite a successful build, so checking the name and table connection is necessary.","Startup refers to EXTI0_1_IRQHandler in its interrupt vector table. A matching strong function definition replaces the weak default during linking. The table therefore contains the address of your function. A differently spelled function does not replace that symbol. The default handler can still run and wait forever when the interrupt arrives.",'nm T means a strong text symbol; W means weak. The table has external IRQ slots starting at index 16. EXTI IRQ 5 occupies index 21. Inspect vector value as well as symbol name.','In lesson 05 toggle handler-name fault. Trace why build success cannot detect the intended connection.','04_Startup_And_LinkerScript/startup.c',undefined,["Startup refers to EXTI0_1_IRQHandler in its interrupt vector table.", "A matching strong function definition replaces the weak default during linking.", "The table therefore contains the address of your function.", "A differently spelled function does not replace that symbol.", "The default handler can still run and wait forever when the interrupt arrives."],"The handler name must match the vector symbol exactly."),
topic("Why startup configures clock and printf output","The clock supplies the repeated timing signals that make the CPU and peripherals run. Startup changes its speed and records that speed for later calculations. The C function printf formats characters, but sending them requires a separate output function connected to the serial peripheral.","Timer periods and serial bit timing are calculated from the configured clock speed. If that speed is described incorrectly, the calculations are wrong; if printf has no connected output function, its formatted characters cannot reach the serial pins.","Startup increases Flash wait states so instruction reads remain valid at the faster clock. It changes the clock divider and records 48 MHz in SystemCoreClock. Library initialization runs before main. When printf produces characters, the _write backend waits for the serial transmitter to be ready. It writes each character to USART2, the hardware unit connected to the serial pins.",'SystemCoreClock is a software variable describing configured clock, not a frequency measurement. __libc_init_array runs library initialization before main. Course _sbrk allocates heap but is not a complete bounds-checking allocator; student projects need memory discipline.','Step startup to clock stage. Explain what must change if oscillator/divider settings change, and why printf can hold the main loop.','04_Startup_And_LinkerScript/retarget.c',undefined,["Startup increases Flash wait states so instruction reads remain valid at the faster clock.", "It changes the clock divider and records 48 MHz in SystemCoreClock.", "Library initialization runs before main.", "When printf produces characters, the _write backend waits for the serial transmitter to be ready.", "It writes each character to USART2, the hardware unit connected to the serial pins."],"SystemCoreClock describes the configured clock; _write gives printf a physical output path.")
],'Skipping .data copy while clearing .bss produces what?', ['All globals are correct','Initialized witness wrong; zero-initialized witness correct','Flash instructions disappear'],1,['The initial .data bytes remain in Flash but have not reached writable RAM.','Correct. Each startup loop keeps a different C promise.','Copying globals does not alter program instructions in Flash.'],[['Reset_Handler','Software entry after reset hardware loads initial state.'],['Weak alias','A default name connected to a fallback function; the linker lets a matching normal (strong) definition replace it.'],['Linker symbol','Address-valued label assigned by linker; use its address in startup C.'],['Bootstrapping','Minimal fixed hardware action starts progressively more capable software.']],['Reset loads the stack pointer and Reset_Handler address from the vector table; startup later calls main.','The linker marks each data region’s boundaries; startup uses those addresses to copy initial values and clear zeros.','Verify handler connection and clock before trusting board behavior.'],['Faulty-vector model stops at invalid boot words; exact failure depends on misplaced bytes and hardware.']),
lesson(5,'Connect a pin setting to an output and a button to a handler.', ['A store writes to the selected address; some addresses select peripheral controls rather than ordinary memory.','The interrupt controller selects allowed requests; saved CPU values let main resume after the handler.','Volatile preserves accesses to a changing value; it does not stop a handler between a read and a write.'],['GPIO fields and physical pins','Set/reset command register','Active-low buttons and bounce','Complete EXTI→NVIC→handler path'],'A command can change an output bit without driving the intended pin, and a button transition can be detected without running its handler. This lesson checks each required configuration and intermediate value so you can locate why an LED or button does not respond.',[
topic("Connect the selected pin to GPIO output","PA5 is one real pin on the chip. GPIO is the built-in pin controller. It can read a pin or drive it high/low. A saved 0 or 1 is only a request: the pin changes only when its mode connects GPIO to that pin. On this board, PA5 also connects to the green LED.","A pin can connect to different built-in circuits. So saving “1” is not enough to light the LED. The pin must also be set to output mode so GPIO is connected to it.","First allow GPIOA to run by turning on its clock. Set PA5’s mode field to 01, which means output. Write 1 to the output latch. GPIO now drives PA5 high and the LED turns on. Change the mode to analog: the latch still remembers 1, but GPIO no longer drives the pin.",'GPIOA MODER offset0; PA5 field bits 11:10. Modes 00=input,01=output,10=alternate function,11=analog. Course reset GPIOA MODER=0xEBFFFFFF: PA13/14 debug AF, most others analog. ST UM2953 Table 11 maps Arduino CN5 pin6 SCK/D13 to PA5. The lab shows this verified connector→signal→register connection; board layout is functional, not to scale.','Select PA5. Change mode from output to analog; set its latch and explain why the LED no longer follows.','05_GPIO_And_Interrupts/Main.c',undefined,["Turn on the clock for GPIO port A so its pin controls can operate.", "Choose pin PA5 and set its two mode bits to 01, which means output.", "Send a command that makes its remembered output value 1.", "Output mode connects that high level to PA5 and the board LED.", "If you switch to analog mode, the value stays saved but GPIO stops driving the pin."],"The latch remembers the requested level. The mode decides whether that level reaches the pin."),
topic("Why a released button needs a defined voltage","A digital input reports 0 for a low voltage and 1 for a high voltage. A pull-up is a weak electrical connection that holds an otherwise undriven input high. Pressing this button connects the input to ground, making it low. That pressed-is-low convention is called active low.","A released button must produce a predictable reading, and pressed-low must be interpreted correctly. Without a defined released voltage, noise can look like a press; incompatible output drivers can also try to force different voltages onto the same wire.","With the button released, the pull-up holds PA1 high. Pressing connects PA1 to ground and makes the input low. The high-to-low transition is a falling edge that the interrupt detector can record. Without a pull-up or another driver, the released input can float at an unreliable voltage. For outputs, push-pull drives both levels; open-drain drives low and releases for high.",'PUPDR has two-bit fields at 2×pin:00 none,01 pull-up,10 pull-down. OTYPER one bit per pin:0 push-pull,1 open-drain. OSPEEDR two-bit fields. AFR uses four-bit fields and MODER=10; an AF number comes from the device pin table, not a universal peripheral number.','Press virtual PA1 in interrupt path and predict falling pending flag. Explain why no pull-up leaves release level undefined on a real undriven input.','05_GPIO_And_Interrupts/Slide.md',undefined,["With the button released, the pull-up holds PA1 high.", "Pressing connects PA1 to ground and makes the input low.", "The high-to-low transition is a falling edge that the interrupt detector can record.", "Without a pull-up or another driver, the released input can float at an unreliable voltage.", "For outputs, push-pull drives both levels; open-drain drives low and releases for high."],"For this active-low button, released is 1 and pressed is 0."),
topic("Set one output without replacing other outputs","The output data register (ODR) holds the remembered output bits for a GPIO port. The bit set/reset register (BSRR) accepts a command identifying which bits to set or reset. Zero command bits leave the other outputs unchanged, so no read of the old ODR is needed.","Replacing the whole output value can turn off pins controlled by other code. Reading the old value and writing a changed copy can also overwrite a handler’s update; a command naming only the desired changes avoids that extra read-and-write sequence.","Construct a command with bit 5 set to make output 5 high. Store that command at GPIOA BSRR address 0x50000018. Hardware updates ODR bit 5 and keeps the unmentioned bits. To make output 5 low, send command bit 21 instead. Read ODR to inspect the resulting state; BSRR is a command interface.",'BSRR offset0x18. Low 16 bits set; high16 reset; zero means leave unchanged. Simultaneous set/reset for same bit prioritizes set on this device. BSRR is not a stored output-state variable: inspect ODR to read latch state.','Start with two lit pins; reset PA5 using bit 21. Check that other latch bits survive. Select each source line to highlight bus target and field.','_lib/gpio.h','port->BSRR = 1u << pin;\nport->BSRR = 1u << (pin + 16u);',["Construct a command with bit 5 set to make output 5 high.", "Store that command at GPIOA BSRR address 0x50000018.", "Hardware updates ODR bit 5 and keeps the unmentioned bits.", "To make output 5 low, send command bit 21 instead.", "Read ODR to inspect the resulting state; BSRR is a command interface."],"BSRR selects changes; ODR shows the stored output state."),
topic("How contact bounce produces several apparent presses","An edge is a transition between low and high levels. Mechanical switch contacts can touch and separate several times during one press. This bounce produces several edges even though the person intended one action. Debouncing means deciding when a stable level represents an accepted press or release.","One physical press can produce several quick electrical transitions. Counting each as a separate action duplicates the user’s request, while waiting too long for stability can reject a genuinely brief press.","The contact first changes from released high to pressed low. Bouncing briefly changes the level back and forth. Edge detection records those transitions without knowing the intended action. Sampling reads the level only at the selected sample times. A quiet-time filter accepts a transition after the candidate level stays unchanged long enough.",'Course button A uses debounce_step at approximately1 kHz; button B ISR counts edges and main applies quiet-time decision. Polling is sampling, not a guaranteed debounce filter. COUNTFLAG latches one wrap, not a queue of missed milliseconds; printf can make lesson 05’s time run slow.','Reduce quiet time below bounce duration, then increase it beyond a brief press. Predict duplicate transitions versus missed press.','05_GPIO_And_Interrupts/Main.c',undefined,["The contact first changes from released high to pressed low.", "Bouncing briefly changes the level back and forth.", "Edge detection records those transitions without knowing the intended action.", "Sampling reads the level only at the selected sample times.", "A quiet-time filter accepts a transition after the candidate level stays unchanged long enough."],"An edge is an electrical transition; one accepted press may require filtering several edges."),
topic("How a button request reaches its handler","The external interrupt/event controller (EXTI) detects configured pin transitions and remembers them as pending flags. The NVIC decides whether their interrupt request may run. A vector identifies the handler address. Each part must be configured, and the handler must clear the source after servicing it.","Detecting a pin change does not guarantee that the correct handler runs. A disabled delivery step leaves the event waiting, a wrong function connection runs the fallback, and a source left set can request the handler repeatedly.","Routing connects PA1 to EXTI line 1, and falling-edge detection records the press. The EXTI pending flag remains set while its interrupt mask and NVIC delivery settings are checked. If IRQ 5 is enabled and eligible, the CPU saves the interrupted state. Vector slot 21 supplies the handler address. The handler clears the EXTI source and counts the event. Exception return restores main, which decides whether the event is an accepted press.",'STM32C0 EXTI EXTICR stores one eight-bit slot per line; port selection uses documented code A=0,B=1,C=2. Line n maps to index n/4, shift(n%4)×8. GPIO interrupts group 0–1,2–3,4–15. EXTI RPR1/FPR1 are write-one-to-clear; use assignment, not a read-modify-write OR.','Disable NVIC, press, inspect FPR1=2 and running main. Restore NVIC, disable clear, and identify why useful main progress stops.','05_GPIO_And_Interrupts/Main.c',undefined,["Routing connects PA1 to EXTI line 1, and falling-edge detection records the press.", "The EXTI pending flag remains set while its interrupt mask and NVIC delivery settings are checked.", "If IRQ 5 is enabled and eligible, the CPU saves the interrupted state.", "Vector slot 21 supplies the handler address.", "The handler clears the EXTI source and counts the event.", "Exception return restores main, which decides whether the event is an accepted press."],"Detection, delivery, handler connection and clearing are separate steps to inspect."),
topic("How the CPU preserves interrupted values","The interrupted program has working values and a place to resume. The CPU saves an exception frame, a group of these values, before entering a handler. The compiler preserves other required registers. Exception return restores that frame so ordinary code can continue its calculation.","The handler needs some of the same working registers as the code it interrupts. Preserving the earlier values lets the handler use those registers without corrupting the calculation that resumes afterward.","Exception entry saves R0–R3, R12, LR, PC and xPSR on the interrupted stack. The saved PC identifies the resume instruction and xPSR contains status. The handler runs in Handler mode using the main stack pointer. Its special LR value, EXC_RETURN, identifies how to return from the exception. Exception return reloads the saved frame and resumes the interrupted instructions.",'Basic frame is eight words plus possible alignment padding. If Thread used PSP, entry stacks there; handler itself uses MSP. NVIC priority 2 means CMSIS encoded high bits0x80 on this two priority-bit device. Pending is distinct from active. Clearing peripheral source is distinct from clearing NVIC pending.','Step entry and return separately. State whose stack holds interrupted values and where saved PC sends the CPU afterward.','05_GPIO_And_Interrupts/Slide.md',undefined,["Exception entry saves R0–R3, R12, LR, PC and xPSR on the interrupted stack.", "The saved PC identifies the resume instruction and xPSR contains status.", "The handler runs in Handler mode using the main stack pointer.", "Its special LR value, EXC_RETURN, identifies how to return from the exception.", "Exception return reloads the saved frame and resumes the interrupted instructions."],"The exception frame preserves interrupted work; the handler has temporary use of the CPU."),
topic("Find the first failed step in an interrupt path","A working button interrupt needs a complete chain from pin configuration to source clearing. Debugging means inspecting the intermediate state to find where an expected effect stops. This is more informative than changing several settings at once because the first missing result identifies the part needing attention.","Several different missing settings can produce the same visible symptom: no response to a button. Inspecting intermediate states shows whether detection, delivery or handling failed, allowing you to change the relevant setting rather than disturb working ones.","Check the clock, input mode, pull-up and observed pin level. Check EXTI port routing and edge detection, then inspect its pending flag. If pending is set, check the EXTI mask and NVIC enable and priority. If delivery works, inspect the vector address and actual handler. Finally check that the handler clears the source so normal work can continue.",'Course lab proposes SWIER1 at EXTI base+0x08 and NVIC ISPR at 0xE000E200; IRQ 5 bit is32. A direct NVIC pending request can enter a handler while EXTI has no event, so handler must inspect source flags. Pinned lab says debugger writes were not yet observed in Wokwi.','With handler-name fault active, identify last successful hop. Explain why button C on PC13 requires port-C routing and EXTI4_15 handler rather than copying PA1 setup unchanged.','05_GPIO_And_Interrupts/Lab.md',undefined,["Check the clock, input mode, pull-up and observed pin level.", "Check EXTI port routing and edge detection, then inspect its pending flag.", "If pending is set, check the EXTI mask and NVIC enable and priority.", "If delivery works, inspect the vector address and actual handler.", "Finally check that the handler clears the source so normal work can continue."],"Look for the first expected state change that did not happen.")
],'EXTI FPR1 bit 1 is set but NVIC IRQ 5 is disabled. What happens?', ['Main keeps running; edge remains pending at EXTI','Handler runs because pending overrides enable','CPU always HardFaults'],0,['Correct. Detection worked; delivery gate is closed. Inspect both rather than blaming the button.','Enable and priority eligibility are separate conditions from pending state.','A disabled interrupt is ordinary configured behavior, not a fault.'],[['GPIO','General-purpose input/output peripheral.'],['MODER','Two-bit fields selecting input, output, alternate-function or analog mode.'],['ODR / BSRR','Output latch state / commands to set and reset selected latch bits.'],['EXTI','External interrupt/event controller detecting and latching edges.'],['NVIC','Nested vectored interrupt controller selecting eligible exceptions.'],['ISR','Interrupt service routine: handler software for an interrupt.'],['Bounce','Short repeated contact transitions around a mechanical press/release.'],['Active low','The active condition, such as a pressed button, is represented by low voltage and a read value of 0.'],['EXC_RETURN','A special value in LR that tells the CPU to restore an exception frame and which stack and mode to resume.']],['The remembered latch value, selected pin mode, enabled clock and physical pin level are separate states.','Trace pin transition, EXTI pending flag, interrupt masks, NVIC delivery, vector address and source clearing in order.','Record the event briefly in the handler, then decide whether it represents a stable press in main.'],['Electrical output model omits load current, analog voltage levels and edge slew. Bounce timing is deterministic teaching data, not measured contact behavior.']),
lesson(6,'Use hardware timers to create pulses and measure elapsed time.', ['A pin mode can connect a hardware peripheral, such as a timer, to a physical signal.','An event can remain pending until allowed to run; the handler must clear its source using that device’s documented rule.'],['SysTick timebase','Prescaler/counter/reload','PWM and preloads','Capture and timing error','Nonblocking periodic jobs'],'The CPU may be busy when a pulse should change or an input edge arrives. Hardware timers can create the pulse or save the edge time independently. Calculating their settings and comparing saved times with delayed handler reads shows which timing guarantees each approach provides.',[
topic("How elapsed-time subtraction works across wrap","A timestamp is a saved counter reading representing a time. An unsigned counter eventually wraps from its largest value to zero. Subtracting the previous timestamp using the same unsigned width gives elapsed time across that wrap, provided the true interval fits within the counter range.","A clock eventually returns to zero, making a simple comparison of large and small timestamps misleading. Elapsed-time subtraction handles that wrap and lets a program check whether work is due without sitting in a delay that prevents other jobs.","Save a previous millisecond timestamp near 0xFFFFFFFF. As time advances, the 32-bit timestamp wraps to small values. Unsigned subtraction of current minus previous also wraps in the same number range. From 0xFFFFFFF0 to 0x10 the result is 32 milliseconds. A periodic job compares that elapsed value with its interval while other jobs keep running.",'SysTick is a 24-bit down-counter. SysTick_Config(48000) sets LOAD 47999, VAL 0, lowest priority and core clock+interrupt enable. SysTick_Handler increments a 32-bit ms_ticks. Multiple SysTick wraps can coalesce if interrupts are blocked too long; ticks are not an infinite queue.','Compute elapsed from0xFFFFFFF0 to0x10. Explain why32 milliseconds, not a negative value.','06_Time_And_Timers/Main.c',undefined,["Save a previous millisecond timestamp near 0xFFFFFFFF.", "As time advances, the 32-bit timestamp wraps to small values.", "Unsigned subtraction of current minus previous also wraps in the same number range.", "From 0xFFFFFFF0 to 0x10 the result is 32 milliseconds.", "A periodic job compares that elapsed value with its interval while other jobs keep running."],"Use unsigned current-minus-previous for bounded elapsed intervals, including a wrap."),
topic("How the prescaler and reload set the period","A timer counter advances on clock ticks. Its prescaler divides the input clock so ticks arrive more slowly. Its auto-reload register sets the largest count before restarting at zero. Both settings use an inclusive count, which is why each stored value contributes one more than its number.","A loop waiting in software can take longer when other work interrupts it. A configured hardware timer keeps counting independently, giving a period you can calculate from the clock and both inclusive count settings.","A 48 MHz clock supplies 48 million ticks each second. Prescaler PSC 47 divides by 48, producing one counter tick per microsecond. The counter visits 0 through ARR 19999, a total of 20,000 ticks. It restarts at zero after 20 milliseconds. That repeated update occurs 50 times per second without a CPU delay loop.",'f_update=f_timer/((PSC+1)(ARR+1)). This lesson assumes configured 48 MHz timer clock; other clock-tree configurations need their own timer input calculation. TIM3 and TIM14 clock gates are APBENR1/APBENR2 respectively.','Set PSC 48 instead of47. Predict why frequency becomes about 48.98  Hz despite correct-looking code.','06_Time_And_Timers/Main.c',undefined,["A 48 MHz clock supplies 48 million ticks each second.", "Prescaler PSC 47 divides by 48, producing one counter tick per microsecond.", "The counter visits 0 through ARR 19999, a total of 20,000 ticks.", "It restarts at zero after 20 milliseconds.", "That repeated update occurs 50 times per second without a CPU delay loop."],"The timer period uses both PSC + 1 and ARR + 1."),
topic("How hardware repeats a high pulse","Pulse-width modulation (PWM) repeats a signal that is high for part of each period. In this timer mode the output is high while the count is below the compare register (CCR1), then low for the rest. The compare value therefore determines high duration; the reload value determines the whole period.","Making each signal change in software requires the CPU to be available at that instant. A timer comparison creates repeated pulses without that repeated CPU work or the changing delays of interrupt handlers.","The counter starts a period at zero. With CCR1 1500 and one-microsecond ticks, it remains below the threshold for 1500 microseconds. At the threshold the hardware output becomes low. The counter continues until the 20,000-tick period ends and repeats. Correct pin routing connects that channel to PA6, allowing the pulse to reach the pin.",'At1 MHz CCR1 = 1500 means1.5 ms; ARR 19999 gives20 ms frame,7.5% duty. Hobby servo typically interprets pulse width rather than brightness-style duty, with nominal1–2 ms range that varies by servo. This model makes no calibrated angle claim.','Change pulse width while preserving frame; then change frame while preserving pulse width. Explain which servo command remained the same.','06_Time_And_Timers/Main.c',undefined,["The counter starts a period at zero.", "With CCR1 1500 and one-microsecond ticks, it remains below the threshold for 1500 microseconds.", "At the threshold the hardware output becomes low.", "The counter continues until the 20,000-tick period ends and repeats.", "Correct pin routing connects that channel to PA6, allowing the pulse to reach the pin."],"Compare sets the high duration; reload sets how often the pulse repeats."),
topic("Why buffered settings wait for a period boundary","Changing a timer threshold during a pulse can change that pulse unexpectedly. Preload holds a requested setting until an update event transfers it to the active value, often called the shadow value. This lets a completed period use one consistent setting.","Applying a new threshold halfway through a period can shorten or lengthen the current pulse unexpectedly. Holding the request until the next update keeps each period consistent, and transferring setup values establishes the intended first period.","Write a new requested compare value while the timer is running. With compare preload enabled, the active threshold stays unchanged during the current period. At the next update, hardware transfers the request into the active threshold. The next period uses the new value from its start. During setup, forcing EGR.UG transfers buffered settings and also sets the update flag, which software clears.",'PSC is buffered; ARR buffering depends on ARPE; CCR1 buffering depends on OC1PE. UG also raises UIF, so clear it before enabling update IRQ. TIM SR flags are write-zero-to-clear, opposite to EXTI. Write ~TIM_SR_UIF leaves other flags unaffected.','Toggle preload in the counter experiment and change CCR during high phase. Compare current pulse versus next-frame change.','06_Time_And_Timers/Main.c',undefined,["Write a new requested compare value while the timer is running.", "With compare preload enabled, the active threshold stays unchanged during the current period.", "At the next update, hardware transfers the request into the active threshold.", "The next period uses the new value from its start.", "During setup, forcing EGR.UG transfers buffered settings and also sets the update flag, which software clears."],"Preload keeps the current period consistent and applies the request at an update."),
topic("Why input capture measures the edge time","Input capture is hardware that copies the current timer count into a capture register when a configured signal edge arrives. The handler can read it later. Reading the live counter in the handler instead records the later handler time, so unequal delays at two edges distort measured pulse width.","The handler may begin after the edge, and that delay may differ for rising and falling edges. Reading the live count then adds those delays to the measured width; saving the count in hardware at each edge avoids that particular error.","The rising edge arrives and capture stores the current counter value. The falling edge later stores its counter value. Software reads the saved timestamps and subtracts them using the counter width. A handler reading the live counter instead adds its own delay to each timestamp. Different rising and falling delays change that calculated width; saved capture timestamps avoid this delay error.",'TIM14 CH1 on PA7 AF4 captures both edges;16-bit modular subtraction handles one wrap when pulse shorter than timer modulus. Reading CCR1 in input-capture mode clears CC1IF according to documented sequence. Course HC-SR04 computation is width/58 cm; sensor physics and temperature affect real conversion.','Set rise delay10  µs and fall delay100  µs. Predict EXTI width 90  µs too long while capture width remains unchanged.','06_Time_And_Timers/Main.c',undefined,["The rising edge arrives and capture stores the current counter value.", "The falling edge later stores its counter value.", "Software reads the saved timestamps and subtracts them using the counter width.", "A handler reading the live counter instead adds its own delay to each timestamp.", "Different rising and falling delays change that calculated width; saved capture timestamps avoid this delay error."],"Capture records when the edge happened; a handler read records when software got there."),
topic("Separate modeled capture from the simulator fallback","A simulator implements selected hardware behavior. Firmware can build correctly while waiting for a feature the simulator does not implement. The pinned course reports a fallback that detects pin edges with EXTI and reads the timer in software. It enables progress but carries handler delay into the measurement.","Correct code can wait for an event that a simulator never produces. Checking the reported feature behavior and naming the fallback mechanism lets you continue testing while accounting for the different measurement delay.","The course firmware attempts timer input capture in Wokwi. The reported run has pin edges but no completed captures. The fallback uses an EXTI handler to read the live timer count. It reports which mechanism supplied the measurement so the result can be interpreted correctly. This browser model separately compares ideal capture with delayed handler reads.",'The course’s2026-10-04 Wokwi observation: cap 0 with EXTI edges present. Renode timer frequency had to be corrected from 10 MHz to48 MHz in an earlier harness. These are repository-reported observations; browser plots are deterministic educational simulations.','Compare capture and delayed EXTI in this model. Explain why a working fallback is useful but does not make their mechanisms equivalent.','06_Time_And_Timers/README.md',undefined,["The course firmware attempts timer input capture in Wokwi.", "The reported run has pin edges but no completed captures.", "The fallback uses an EXTI handler to read the live timer count.", "It reports which mechanism supplied the measurement so the result can be interpreted correctly.", "This browser model separately compares ideal capture with delayed handler reads."],"A fallback can provide useful data while measuring time by a different mechanism.")
],'CNT is read100  µs after an edge. How can measurement avoid that delay?', ['Read CNT in a longer handler','Use input capture’s saved CCR timestamp','Increase main-loop speed only'],1,['A later live counter read includes more delay.','Correct. Hardware saves CNT at the edge; handler timing changes when you collect it, not its recorded time.','Faster software may reduce average delay but not remove variable latency.'],[['SysTick','A counter in the ARM CPU that counts down and can request a handler periodically; software uses it to maintain time.'],['PSC / ARR / CCR','PSC sets the clock divisor as PSC + 1; ARR sets the last count; CCR holds an output comparison threshold or an input timestamp.'],['PWM','Pulse-width modulation: hardware compares count with threshold each cycle.'],['Input capture','Hardware copies timer count into capture register at a configured input edge.'],['Preload','Requested setting stored until an update event transfers it to active shadow state.'],['UIF','Update interrupt flag: a timer status bit recording an update event. Writing zero clears it; writing one leaves it unchanged.']],['The clock divisor is PSC + 1, and a period contains ARR + 1 counter ticks.','Hardware draws or timestamps edges independently of CPU.','Capture stores the count at the edge; an interrupt handler reading the live count includes its response delay.'],['Educational event model, not peripheral emulation. Real servo range and hardware timing are not measured here.'])
];
